import{_ as l,a0 as o,w as u,s as r,ao as p,I as i,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221012 How to Set Static IP Address on Ubuntu Server 22.04","title":"如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址","tag":"202210","desc":""},"relativePath":"202210/20221012 How to Set Static IP Address on Ubuntu Server 22.04.md","filePath":"[post].md"}'),d={name:"202210/20221012 How to Set Static IP Address on Ubuntu Server 22.04.md"};function c(g,s,h,b,k,m){const t=o("Link");return u(),r("div",null,[s[18]||(s[18]=p('<h1 id="如何在-ubuntu-服務器-22-04-上設置靜態-ip-地址" tabindex="-1">如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 <a class="header-anchor" href="#如何在-ubuntu-服務器-22-04-上設置靜態-ip-地址" aria-label="Permalink to “如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/27/091312aohaix6g6kay68xa.jpg" alt=""></p><blockquote><p>在這篇文章中，我們將介紹如何在 Ubuntu 服務器 22.04 上設置靜態 IP 地址。</p></blockquote><p>強烈建議在 Linux 服務器上使用靜態 IP，因為它會在重啓後保持不變。靜態 IP 對郵件服務器、Web 服務器和文件服務器等服務器起着重要作用。</p><p><strong>準備條件</strong></p><ul><li>最小安裝的 Ubuntu 服務器 22.04</li><li>具有 <code>sudo</code> 管理員權限的普通用户</li></ul><p>在 Ubuntu 服務器 22.04 中，網絡由 netplan 程序控制，因此我們將使用 netplan 在 Ubuntu 服務器上配置靜態 IP 地址。</p>',7)),i("p",null,[s[1]||(s[1]=n("注意：我們不能使用 ",-1)),e(t,{href:"https://www.linuxtechi.com/configure-ip-with-nmcli-command-linux/"},{default:a(()=>[...s[0]||(s[0]=[n("nmcli 程序",-1)])]),_:1}),s[2]||(s[2]=n("，因為它不是 Ubuntu 服務器上默認安裝的一部分。",-1))]),s[19]||(s[19]=p(`<h3 id="在-ubuntu-服務器-22-04-上設置靜態-ip-地址" tabindex="-1">在 Ubuntu 服務器 22.04 上設置靜態 IP 地址 <a class="header-anchor" href="#在-ubuntu-服務器-22-04-上設置靜態-ip-地址" aria-label="Permalink to “在 Ubuntu 服務器 22.04 上設置靜態 IP 地址”">​</a></h3><p>登錄到你的 Ubuntu 服務器 22.04，查找 netplan 配置文件。它位於 <code>/etc/netplan</code> 目錄下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/netplan/</span></span>
<span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 116 Oct 12 04:03 00-installer-config.yaml</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>運行以下 <code>cat</code> 命令以查看 <code>00-installer-config.yaml</code> 的內容。</p><p>注意：配置文件的名稱可能因你的設置而異。由於它是一個 yaml 文件，因此請確保在編輯時保持縮進和語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat 00-installer-config.yaml</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/Default-Content-netplan-ubuntu-server.png" alt="Default-Content-netplan-ubuntu-server"></p><p>根據上面的輸出，它説我們有 <code>ens33</code> 接口，它正在從 DHCP 服務器獲取 IP。查看接口名稱的另一種方法是通過 <code>ip</code> 命令。</p><p>現在，要配置靜態 IP 代替 DHCP，使用 <code>vi</code> 或 <code>nano</code> 編輯器編輯 netplan 配置文件並添加以下內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi 00-installer-config.yaml</span></span>
<span class="line"><span># This is the network config written by &#39;subiquity&#39;</span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>  renderer: networkd</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    ens33:</span></span>
<span class="line"><span>      addresses:</span></span>
<span class="line"><span>        - 192.168.1.247/24</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [4.2.2.2, 8.8.8.8]</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - to: default</span></span>
<span class="line"><span>          via: 192.168.1.1</span></span>
<span class="line"><span>  version: 2</span></span></code></pre></div><p>保存並關閉文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/Updated-Netplan-Config-File-Content-Ubuntu-Server.png" alt="Updated-Netplan-Config-File-Content-Ubuntu-Server"></p><p>在上面的文件中，我們使用了以下內容，</p><ul><li><code>ens33</code> 為接口名稱</li><li>用於設置靜態 IP 的地址</li><li><code>nameservers</code> 用於指定 DNS 服務器的 IP</li><li>用於指定默認網關的路由</li></ul><p>注意：根據你的環境更改 IP 詳細信息和接口名稱。</p><p>要是上述修改生效，請使用以下 <code>netplan</code> 命令應用這些更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo netplan apply</span></span></code></pre></div><p>運行以下 IP 命令查看接口上的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr show ens33</span></span></code></pre></div><p>要查看默認路由，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip route show</span></span></code></pre></div><p>上述命令的輸出。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/ip-addr-route-command-output-ubuntu-server.png" alt="ip-addr-route-command-output-ubuntu-server"></p><p>完美，以上命令的輸出確認靜態 IP 和路由配置成功。</p><p>這就是這篇文章的全部內容。請在下面的評論部分發表你的問題和反饋。</p><hr>`,27)),i("p",null,[s[4]||(s[4]=n("via: ",-1)),e(t,{href:"https://www.linuxtechi.com/static-ip-address-on-ubuntu-server/"},{default:a(()=>[...s[3]||(s[3]=[n("https://www.linuxtechi.com/static-ip-address-on-ubuntu-server/",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=n("作者：",-1)),e(t,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...s[5]||(s[5]=[n("Pradeep Kumar",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),e(t,{href:"https://github.com/lkxed"},{default:a(()=>[...s[6]||(s[6]=[n("lkxed",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[7]||(s[7]=[n("geekpi",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const P=l(d,[["render",c]]);export{C as __pageData,P as default};
